import { NextResponse } from 'next/server';
import { sendLowStockAlert } from '@/lib/email';
import { z } from 'zod';

const AlertSchema = z.object({
  productName: z.string(),
  currentStock: z.number(),
  minStock: z.number(),
});

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const { productName, currentStock, minStock } = AlertSchema.parse(body);

    // Run asynchronously, don't block response
    sendLowStockAlert(productName, currentStock, minStock).catch(console.error);

    return NextResponse.json({ success: true });
  } catch (error) {
    return NextResponse.json({ error: 'Invalid request' }, { status: 400 });
  }
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { ShoppingCart } from 'lucide-react';
import type { CartItem, SaleResult, ProductView, SaleType, AfipStatus, DailySummary, Client } from '@/lib/types';
import { createSale, getAfipStatus, getDailySummary } from '@/lib/api/client';
import { StatusBar } from '@/components/StatusBar';
import { ProductPanel } from '@/components/ProductPanel';
import { CartPanel } from '@/components/CartPanel';
import { ResultModal } from '@/components/ResultModal';
import { AdminDashboard } from '@/components/admin/AdminDashboard';

export default function POSPage() {
  // --- State ---
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [saleResult, setSaleResult] = useState<SaleResult | null>(null);
  const [saleError, setSaleError] = useState<string | null>(null);
  const [afipStatus, setAfipStatus] = useState<AfipStatus | null>(null);
  const [dailySummary, setDailySummary] = useState<DailySummary | null>(null);
  const [isMobileCartOpen, setIsMobileCartOpen] = useState(false);
  const [showAdmin, setShowAdmin] = useState(false);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);

  // --- Effects ---
  useEffect(() => {
    // Load AFIP status & daily summary on mount
    getAfipStatus().then(setAfipStatus).catch(console.error);
    getDailySummary().then(setDailySummary).catch(console.error);

    // Refresh summary every 5 minutes
    const interval = setInterval(() => {
      getDailySummary().then(setDailySummary).catch(console.error);
    }, 5 * 60 * 1000);

    return () => clearInterval(interval);
  }, []);

  // --- Cart Operations ---
  const handleAddToCart = useCallback((product: ProductView) => {
    setCart((prev) => {
      const existing = prev.find((item) => item.product.id === product.id);
      if (existing) {
        if (existing.quantity >= product.stock) return prev;
        return prev.map((item) =>
          item.product.id === product.id
            ? { ...item, quantity: item.quantity + 1 }
            : item,
        );
      }
      return [...prev, { product, quantity: 1 }];
    });
  }, []);

  const handleUpdateQty = useCallback((productId: number, delta: number) => {
    setCart((prev) =>
      prev
        .map((item) => {
          if (item.product.id !== productId) return item;
          const newQty = item.quantity + delta;
          if (newQty <= 0) return null;
          if (newQty > item.product.stock) return item;
          return { ...item, quantity: newQty };
        })
        .filter(Boolean) as CartItem[],
    );
  }, []);

  const handleRemove = useCallback((productId: number) => {
    setCart((prev) => prev.filter((item) => item.product.id !== productId));
  }, []);

  // --- Checkout ---
  const handleCheckout = useCallback(
    async (type: SaleType) => {
      if (cart.length === 0 || isProcessing) return;
      setIsProcessing(true);
      setSaleResult(null);
      setSaleError(null);

      try {
        const result = await createSale({
          items: cart.map((item) => ({
            productId: item.product.id,
            quantity: item.quantity,
          })),
          type,
        });

        setSaleResult(result);
        setCart([]);
        setIsMobileCartOpen(false);

        // Refresh daily summary after successful sale
        getDailySummary().then(setDailySummary).catch(console.error);
      } catch (err: any) {
        setSaleError(err.message || 'Error desconocido al procesar la venta');
      } finally {
        setIsProcessing(false);
      }
    },
    [cart, isProcessing],
  );

  const handleCloseModal = useCallback(() => {
    setSaleResult(null);
    setSaleError(null);
  }, []);

  // --- Admin Mode ---
  if (showAdmin) {
    return <AdminDashboard onExit={() => setShowAdmin(false)} />;
  }

  const totalItems = cart.reduce((sum, item) => sum + item.quantity, 0);

  return (
    <div className="flex flex-col h-screen" style={{ backgroundColor: 'var(--bg-primary)' }}>
      {/* Status Bar */}
      <StatusBar
        status={afipStatus}
        summary={dailySummary}
        onAdminClick={() => setShowAdmin(true)}
      />

      {/* Main Content */}
      <div className="flex flex-1 overflow-hidden relative">
        {/* Product Panel (Left) */}
        <div className="flex-1 flex flex-col overflow-hidden" style={{ backgroundColor: 'var(--bg-tertiary)' }}>
          <ProductPanel onAddToCart={handleAddToCart} />
        </div>

        {/* Cart Panel (Right - Desktop) */}
        <div className={`
          fixed inset-0 z-40 flex flex-col lg:static lg:flex lg:flex-col lg:min-w-[340px] lg:max-w-[420px] transition-transform duration-300 ease-in-out
          ${isMobileCartOpen ? 'translate-y-0' : 'translate-y-full lg:translate-y-0'}
        `} style={{ backgroundColor: 'var(--cart-bg)' }}>
          {/* Mobile Cart Header (Close Button) */}
          <div className="lg:hidden flex items-center justify-between p-4 shrink-0" style={{ borderBottom: '1px solid var(--border-primary)' }}>
             <h2 className="text-lg font-bold" style={{ color: 'var(--text-primary)' }}>Ticket Actual</h2>
             <button 
               onClick={() => setIsMobileCartOpen(false)}
               className="p-2" style={{ color: 'var(--text-tertiary)' }}
             >
               Cerrar
             </button>
          </div>

          <div className="flex-1 min-h-0">
            <CartPanel
              items={cart}
              onUpdateQty={handleUpdateQty}
              onRemove={handleRemove}
              onCheckout={handleCheckout}
              isProcessing={isProcessing}
              selectedClient={selectedClient}
              onSelectClient={setSelectedClient}
            />
          </div>
        </div>
      </div>

      {/* Mobile Cart FAB */}
      {!isMobileCartOpen && (
        <button
          onClick={() => setIsMobileCartOpen(true)}
          className="lg:hidden fixed bottom-6 right-6 z-30 w-16 h-16 rounded-full shadow-lg flex items-center justify-center hover:scale-105 active:scale-95 transition-transform"
          style={{ backgroundColor: 'var(--accent)', color: 'var(--text-inverse)' }}
          id="mobile-cart-fab"
        >
          <ShoppingCart className="w-6 h-6" />
          {totalItems > 0 && (
            <span className="absolute -top-1 -right-1 text-white text-xs font-bold w-5 h-5 rounded-full flex items-center justify-center" style={{ backgroundColor: 'var(--danger)' }}>
              {totalItems}
            </span>
          )}
        </button>
      )}

      {/* Result Modal */}
      <ResultModal
        result={saleResult}
        error={saleError}
        onClose={handleCloseModal}
      />
    </div>
  );
}

'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import { Search, Loader2, Package, AlertTriangle } from 'lucide-react';
import type { ProductView } from '@/lib/types';
import { searchProducts } from '@/lib/api/client';

interface ProductPanelProps {
  onAddToCart: (product: ProductView) => void;
}

function formatCurrency(amount: number): string {
  return new Intl.NumberFormat('es-AR', {
    style: 'currency',
    currency: 'ARS',
    minimumFractionDigits: 2,
  }).format(amount);
}

export function ProductPanel({ onAddToCart }: ProductPanelProps) {
  const [query, setQuery] = useState('');
  const [products, setProducts] = useState<ProductView[]>([]);
  const [loading, setLoading] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  // Auto-focus search input on mount (optimized for barcode scanners)
  useEffect(() => {
    inputRef.current?.focus();

    const handleClick = () => {
      setTimeout(() => inputRef.current?.focus(), 100);
    };
    document.addEventListener('click', handleClick);
    return () => document.removeEventListener('click', handleClick);
  }, []);

  // Load all products initially
  useEffect(() => {
    searchProducts('').then(setProducts).catch(console.error);
  }, []);

  // Debounced search
  const handleSearch = useCallback((value: string) => {
    setQuery(value);

    if (debounceRef.current) clearTimeout(debounceRef.current);

    debounceRef.current = setTimeout(async () => {
      setLoading(true);
      try {
        const results = await searchProducts(value);
        setProducts(results);

        // Auto-add if barcode scanner returns exactly one result
        if (value.length >= 8 && results.length === 1) {
          onAddToCart(results[0]);
          setQuery('');
          const allProducts = await searchProducts('');
          setProducts(allProducts);
        }
      } catch (err) {
        console.error('Search failed:', err);
      } finally {
        setLoading(false);
      }
    }, value.length >= 8 ? 100 : 300);
  }, [onAddToCart]);

  return (
    <div className="flex flex-col h-full">
      {/* Search Bar */}
      <div className="p-4 pb-3">
        <div className="relative">
          <Search
            className="absolute left-3.5 top-1/2 -translate-y-1/2 w-5 h-5"
            style={{ color: 'var(--text-muted)' }}
          />
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={(e) => handleSearch(e.target.value)}
            placeholder="Escanear código de barras o buscar producto..."
            className="input-field pl-11 text-base"
            id="product-search"
            autoComplete="off"
          />
          {loading && (
            <Loader2
              className="absolute right-3.5 top-1/2 -translate-y-1/2 w-5 h-5 animate-spin"
              style={{ color: 'var(--accent)' }}
            />
          )}
        </div>
      </div>

      {/* Product Grid */}
      <div className="flex-1 overflow-y-auto px-4 pb-4">
        {products.length === 0 ? (
          <div
            className="flex flex-col items-center justify-center h-full"
            style={{ color: 'var(--text-muted)' }}
          >
            <Package className="w-16 h-16 mb-4 opacity-20" />
            <p className="text-base font-medium">No se encontraron productos</p>
            <p className="text-sm mt-1 opacity-60">Intentá con otro término de búsqueda</p>
          </div>
        ) : (
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-3 pb-24 lg:pb-0">
            {products.map((product, index) => {
              const isOutOfStock = product.stock <= 0;
              const isLowStock = product.stock > 0 && product.stock <= product.minStock;

              return (
                <button
                  key={product.id}
                  onClick={() => onAddToCart(product)}
                  disabled={isOutOfStock}
                  className={`product-card ${isOutOfStock ? 'product-card--disabled' : ''}`}
                  style={{ animationDelay: `${index * 0.04}s` }}
                  id={`product-${product.id}`}
                >
                  {/* Low stock pulse indicator */}
                  {isLowStock && <div className="product-card__low-badge" />}

                  <span className="product-card__barcode">{product.barcode}</span>
                  <span className="product-card__name">{product.name}</span>

                  <div className="mt-auto flex items-end justify-between pt-3">
                    <span className="product-card__price">
                      {formatCurrency(Number(product.price))}
                    </span>
                    <span
                      className={`product-card__stock ${isLowStock ? 'product-card__stock--low' : ''}`}
                    >
                      {isOutOfStock ? 'Sin stock' : `${product.stock} u.`}
                    </span>
                  </div>
                </button>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { BarChart3, Wifi, WifiOff } from 'lucide-react';
import type { AfipStatus } from '@/lib/types';
import { ThemeToggle } from '@/components/ThemeProvider';

interface StatusBarProps {
  status: AfipStatus | null;
  summary: { totalSales: number; totalRevenue: number } | null;
  onAdminClick?: () => void;
}

function formatCurrency(amount: number): string {
  return new Intl.NumberFormat('es-AR', {
    style: 'currency',
    currency: 'ARS',
    minimumFractionDigits: 2,
  }).format(amount);
}

export function StatusBar({ status, summary, onAdminClick }: StatusBarProps) {
  const isOnline = status?.serverStatus === 'ONLINE';
  const isConfigured = status?.configured ?? false;

  return (
    <header
      className="flex items-center justify-between px-5 py-2.5 shrink-0"
      style={{
        background: 'var(--statusbar-bg)',
        borderBottom: '1px solid var(--statusbar-border)',
      }}
    >
      {/* Left: Logo + Admin */}
      <div className="flex items-center gap-3">
        <div className="flex items-center gap-2.5">
          <img src="/logo.svg" alt="POS Logo" className="w-8 h-8 drop-shadow-md" />
          <div className="hidden sm:block">
            <h1 className="text-base font-bold tracking-tight leading-tight" style={{ color: 'var(--statusbar-text)' }}>
              POS <span style={{ color: 'var(--accent)' }}>&</span> Inventario
            </h1>
          </div>
          <h1 className="text-base font-bold sm:hidden" style={{ color: 'var(--statusbar-text)' }}>
            POS
          </h1>
        </div>

        {/* Admin */}
        <button
          onClick={onAdminClick}
          className="p-2 rounded-lg transition-all duration-200"
          style={{
            backgroundColor: 'var(--statusbar-btn-bg)',
            color: 'var(--statusbar-text-muted)',
          }}
          title="Administración"
          id="admin-btn"
          onMouseEnter={(e) => {
            e.currentTarget.style.backgroundColor = 'var(--statusbar-btn-hover)';
            e.currentTarget.style.color = 'var(--accent)';
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.backgroundColor = 'var(--statusbar-btn-bg)';
            e.currentTarget.style.color = 'var(--statusbar-text-muted)';
          }}
        >
          <BarChart3 className="w-4.5 h-4.5" />
        </button>
      </div>

      {/* Right: Summary + Theme + AFIP */}
      <div className="flex items-center gap-3">
        {/* Daily summary */}
        {summary && (
          <div className="hidden md:flex items-center gap-3">
            <div
              className="flex items-center gap-1.5 text-sm px-3 py-1 rounded-lg"
              style={{
                color: 'var(--statusbar-text-muted)',
                background: 'var(--statusbar-btn-bg)',
              }}
            >
              <BarChart3 className="w-3.5 h-3.5" />
              <span className="font-medium">{summary.totalSales}</span>
              <span className="opacity-60">ventas</span>
            </div>
            <div
              className="font-bold font-tabular text-sm px-3 py-1 rounded-lg"
              style={{
                color: 'var(--accent)',
                background: 'rgba(16, 185, 129, 0.08)',
              }}
            >
              {formatCurrency(summary.totalRevenue)}
            </div>
          </div>
        )}

        {/* Theme Toggle */}
        <ThemeToggle />

        {/* AFIP Status */}
        <div className={`status-badge ${isOnline ? 'status-online' : 'status-offline'}`}>
          <span className={isOnline ? 'dot-online' : 'dot-offline'} />
          <span className="text-xs font-medium">
            AFIP: {!isConfigured ? 'No Config.' : isOnline ? 'En Línea' : 'Sin Conexión'}
          </span>
        </div>
      </div>
    </header>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { X, Save, Loader2 } from 'lucide-react';
import type { ProductView } from '@/lib/types';
import { createProduct, updateProduct } from '@/lib/api/client';

interface ProductFormModalProps {
  product?: ProductView;
  onClose: (shouldRefresh: boolean) => void;
}

export function ProductFormModal({ product, onClose }: ProductFormModalProps) {
  const [formData, setFormData] = useState({
    barcode: '',
    name: '',
    description: '',
    price: 0,
    stock: 0,
    minStock: 5
  });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (product) {
      setFormData({
        barcode: product.barcode,
        name: product.name,
        description: product.description || '',
        price: Number(product.price),
        stock: product.stock,
        minStock: product.minStock
      });
    }
  }, [product]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setError(null);

    try {
      if (product) {
        const { barcode, ...updateData } = formData;
        await updateProduct(product.id, updateData);
      } else {
        await createProduct(formData);
      }
      onClose(true);
    } catch (err: any) {
      setError(err.message || 'Error al guardar el producto');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center backdrop-blur-sm animate-fade-in"
      style={{ backgroundColor: 'var(--modal-overlay)' }}
    >
      <div className="glass-panel-solid w-full max-w-lg mx-4 flex flex-col max-h-[90vh] overflow-hidden shadow-2xl animate-scale-in">
        <div
          className="flex items-center justify-between p-5"
          style={{ borderBottom: '1px solid var(--border-primary)' }}
        >
          <h3 className="text-xl font-bold" style={{ color: 'var(--text-primary)' }}>
            {product ? 'Editar Producto' : 'Nuevo Producto'}
          </h3>
          <button
            onClick={() => onClose(false)}
            className="transition-colors"
            style={{ color: 'var(--text-tertiary)' }}
            onMouseEnter={(e) => { e.currentTarget.style.color = 'var(--text-primary)'; }}
            onMouseLeave={(e) => { e.currentTarget.style.color = 'var(--text-tertiary)'; }}
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 overflow-y-auto space-y-4">
          {error && (
            <div className="p-3 bg-red-500/10 border border-red-500/20 text-red-500 text-sm rounded">
              {error}
            </div>
          )}

          <div>
            <label className="block text-sm font-medium mb-1" style={{ color: 'var(--text-tertiary)' }}>Código de Barras</label>
            <input
              type="text"
              required
              value={formData.barcode}
              onChange={(e) => setFormData({ ...formData, barcode: e.target.value })}
              className="input-field w-full"
              disabled={!!product}
            />
          </div>

          <div>
            <label className="block text-sm font-medium mb-1" style={{ color: 'var(--text-tertiary)' }}>Nombre</label>
            <input
              type="text"
              required
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              className="input-field w-full"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium mb-1" style={{ color: 'var(--text-tertiary)' }}>Precio</label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2" style={{ color: 'var(--text-muted)' }}>$</span>
                <input
                  type="number"
                  required
                  min="0"
                  step="0.01"
                  value={formData.price}
                  onChange={(e) => setFormData({ ...formData, price: parseFloat(e.target.value) })}
                  className="input-field w-full pl-7"
                />
              </div>
            </div>
            <div>
              <label className="block text-sm font-medium mb-1" style={{ color: 'var(--text-tertiary)' }}>Stock Actual</label>
              <input
                type="number"
                required
                value={formData.stock}
                onChange={(e) => setFormData({ ...formData, stock: parseInt(e.target.value) || 0 })}
                className="input-field w-full"
              />
            </div>
          </div>

           <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium mb-1" style={{ color: 'var(--text-tertiary)' }}>Stock Mínimo</label>
              <input
                type="number"
                required
                min="0"
                value={formData.minStock}
                onChange={(e) => setFormData({ ...formData, minStock: parseInt(e.target.value) || 0 })}
                className="input-field w-full"
              />
            </div>
          </div>

          <div>
           <label className="block text-sm font-medium mb-1" style={{ color: 'var(--text-tertiary)' }}>Descripción (Opcional)</label>
           <textarea
             value={formData.description}
             onChange={(e) => setFormData({...formData, description: e.target.value})}
             className="input-field w-full h-20 resize-none"
           />
          </div>

          <div className="pt-4 flex gap-3">
            <button
              type="button"
              onClick={() => onClose(false)}
              className="btn flex-1 py-2.5"
              style={{
                backgroundColor: 'var(--bg-tertiary)',
                color: 'var(--text-tertiary)',
              }}
            >
              Cancelar
            </button>
            <button
              type="submit"
              disabled={isSubmitting}
              className="btn-fiscal flex-1 py-2.5 flex items-center justify-center gap-2"
            >
              {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
              Guardar
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

// ==========================================================
// API Response Helpers - Standardized error handling
// Equivalent to NestJS exception filters and response patterns
// ==========================================================
import { NextResponse } from 'next/server';
import { ZodError } from 'zod';

/**
 * Wraps an async handler with standardized error handling.
 * Similar to NestJS exception filters but for Next.js route handlers.
 */
export function withErrorHandler(
  handler: (request: Request, context?: any) => Promise<NextResponse>,
) {
  return async (request: Request, context?: any) => {
    try {
      return await handler(request, context);
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : 'Error interno del servidor';
      console.error(`[API Error] ${request.method} ${request.url}:`, errorMessage);

      // Zod validation error (like NestJS ValidationPipe)
      if (error instanceof ZodError) {
        const messages = error.issues.map((issue) => issue.message).join('; ');
        return NextResponse.json(
          { message: messages },
          { status: 400 },
        );
      }

      // Business logic errors (stock, not found, etc.)
      const status = errorMessage.includes('no encontrad')
        ? 404
        : errorMessage.includes('insuficiente') || errorMessage.includes('Ya existe')
          ? 400
          : 500;

      return NextResponse.json(
        { message: errorMessage },
        { status },
      );
    }
  };
}

// ==========================================================
// Products Service - Business Logic Layer
// Equivalent to NestJS ProductsService (@Injectable)
// ==========================================================
import { createServerClient } from '@/lib/supabase/client';
import type { ProductView, CreateProductDto, UpdateProductDto } from '@/lib/types';

/** Maps a Supabase row (snake_case) to frontend ProductView (camelCase). */
function toProductView(row: any): ProductView {
  return {
    id: row.id,
    barcode: row.barcode,
    name: row.name,
    description: row.description,
    price: row.price,
    stock: row.stock,
    minStock: row.min_stock,
    isActive: row.is_active,
    createdAt: row.created_at,
  };
}

/**
 * Search products by barcode or name (partial match).
 * Optimized for barcode scanner input (exact match first, then partial).
 */
export async function searchProducts(query: string): Promise<ProductView[]> {
  const supabase = createServerClient();

  if (!query || query.trim().length === 0) {
    const { data, error } = await supabase
      .from('products')
      .select('*')
      .eq('is_active', true)
      .order('name', { ascending: true })
      .limit(50);

    if (error) throw new Error(`Error buscando productos: ${error.message}`);
    return (data ?? []).map(toProductView);
  }

  const trimmed = query.trim();

  // Priority 1: Exact barcode match (most common for scanners)
  const { data: exactMatch } = await supabase
    .from('products')
    .select('*')
    .eq('barcode', trimmed)
    .eq('is_active', true)
    .limit(1);

  if (exactMatch && exactMatch.length > 0) {
    return exactMatch.map(toProductView);
  }

  // Priority 2: Partial name/barcode search (ilike for case-insensitive)
  const { data, error } = await supabase
    .from('products')
    .select('*')
    .eq('is_active', true)
    .or(`name.ilike.%${trimmed}%,barcode.ilike.%${trimmed}%`)
    .order('name', { ascending: true })
    .limit(20);

  if (error) throw new Error(`Error buscando productos: ${error.message}`);
  return (data ?? []).map(toProductView);
}

